// 转码器启动时注册自己：会话断开后自动消失
zk.create(
  "/transcoders/worker-",
  "10.0.1.7:9000".getBytes(),
  OPEN_ACL_UNSAFE,
  CreateMode.EPHEMERAL_SEQUENTIAL);

// 调用方维护本地可用实例列表；watch 触发后重新读取并再次注册 watch
void refreshWorkers() {
  List<String> children = zk.getChildren("/transcoders", event -> refreshWorkers());
  workers = children.stream()
    .map(child -> readString("/transcoders/" + child))
    .toList();
}

String myNode = zk.create(
  "/election/candidate-",
  serverId.getBytes(),
  OPEN_ACL_UNSAFE,
  CreateMode.EPHEMERAL_SEQUENTIAL);

void elect() {
  List<String> nodes = sorted(zk.getChildren("/election", false));
  if (myNode.equals("/election/" + nodes.get(0))) {
    becomeLeader();
    return;
  }
  String prev = predecessorOf(myNode, nodes);
  if (zk.exists(prev, event -> elect()) == null) {
    elect(); // predecessor already disappeared; re-check immediately
  }
}

String myNode = zk.create(
  "/locks/payment/lock-",
  clientId.getBytes(),
  OPEN_ACL_UNSAFE,
  CreateMode.EPHEMERAL_SEQUENTIAL);

void checkLock() {
  List<String> queue = sorted(zk.getChildren("/locks/payment", false));
  if (myNode.equals("/locks/payment/" + queue.get(0))) {
    enterCriticalSection();
    return;
  }

  String prev = pathOfPredecessor(myNode, queue);
  if (zk.exists(prev, event -> checkLock()) == null) {
    checkLock(); // 前一个刚好已经消失，立刻重新检查
  }
}

void release() {
  zk.delete(myNode, -1);
}
